# Presentation only. Input/output IDs and tab values are the server contract.
ui_table <- function(id, label) {
  div(class = "table-wrapper", role = "region", `aria-label` = label,
      tabindex = "0", tableOutput(id))
}
ui_tab_link <- function(value, label) {
  tags$a(href = "#main_tabs", class = "btn btn-default", `data-ui-tab` = value, label)
}
ui_empty <- function(title, note, ...) {
  div(class = "empty-state", h3(title), p(class = "hint", note), ...)
}
codebookr_ui <- function() {
  fluidPage(
    lang = "ko",
    tags$head(
      tags$meta(charset = "UTF-8"), tags$title("CodebookR | \uc790\ub8cc \uc815\ub9ac"),
      includeCSS(system.file("www", "codebookr.css", package = "codebookr", mustWork = TRUE)),
      includeScript(system.file("www", "codebookr.js", package = "codebookr", mustWork = TRUE))
    ),
    tags$a(class = "skip-link", href = "#workspace", "\uc791\uc5c5 \ud654\uba74\uc73c\ub85c \uac74\ub108\ub6f0\uae30"),
    tags$header(class = "app-header",
      div(h1("CodebookR"), p("\ucf54\ub4dc\ubd81\uc5d0 \ub9de\ucdb0 \uc790\ub8cc\ub97c \uc815\ub9ac\ud558\uace0, \ubd84\uc11d\uc5d0 \ud544\uc694\ud55c \ubcc0\uc218\ub97c \uc900\ube44\ud558\uc138\uc694.")),
      span(class = "local-badge", "\ub0b4 \ucef4\ud4e8\ud130\uc5d0\uc11c \ucc98\ub9ac")),
