    tags$main(id = "workspace", tabindex = "-1",
      tabsetPanel(id = "main_tabs",
        tabPanel("1  \uc790\ub8cc \uc5f0\uacb0", value = "data",
          div(class = "section-heading", h2("\uc790\ub8cc\uc640 \ucf54\ub4dc\ubd81\uc744 \uc5f0\uacb0\ud558\uc138\uc694", tabindex = "-1"),
            p(class = "section-lead", "\ub450 \ud30c\uc77c\uc744 \ubd88\ub7ec\uc624\uba74 \ucf54\ub4dc\ubd81\uc744 \ubc14\ud0d5\uc73c\ub85c \ud655\uc778\ud560 \ub0b4\uc6a9\uacfc \ucc98\ub9ac\ud560 \uc791\uc5c5\uc744 \ucc3e\uc2b5\ub2c8\ub2e4.")),
          fluidRow(class = "upload-grid",
            column(6, div(class = "upload-card",
