              p(class = "hint", "CSV, SPSS, Stata, RDS (\ucd5c\ub300 100MB)"),
              tags$details(class = "compact-details", tags$summary("CSV \uc77d\uae30 \uc635\uc158"),
                selectInput("csv_encoding", "\ubb38\uc790 \uc778\ucf54\ub529", c("UTF-8" = "UTF-8", "\ud55c\uad6d\uc5b4 Windows (CP949)" = "CP949", "EUC-KR" = "EUC-KR")),
                textInput("csv_character_columns", "\ubb38\uc790\ub85c \uc77d\uc744 \ubcc0\uc218\uba85", "", placeholder = "\uc608: respondent_id, region_code"),
                p(class = "hint", "\uc27c\ud45c\ub85c \uad6c\ubd84\ud569\ub2c8\ub2e4. \uc55e\uc790\ub9ac\uac00 0\uc774\uac70\ub098 16\uc790\ub9ac \uc774\uc0c1\uc778 \uc815\uc218 \ucf54\ub4dc\ub294 \uc790\ub3d9\uc73c\ub85c \ubb38\uc790\ub85c \uc77d\uc2b5\ub2c8\ub2e4. \ube48 \uce78\uacfc NA\ub294 \uacb0\uce21\uc73c\ub85c \uc77d\uc2b5\ub2c8\ub2e4. \uc635\uc158\uc744 \ubc14\uafb8\uba74 \uc791\uc5c5\uacfc \uacb0\uacfc\uac00 \ucd08\uae30\ud654\ub429\ub2c8\ub2e4.")),
              div(class = "feedback", role = "status", textOutput("data_feedback")))),
            column(6, div(class = "upload-card",
              fileInput("book_files", "\ucf54\ub4dc\ubd81", accept = c(".pdf", ".xlsx", ".xls", ".csv"), multiple = TRUE,
                buttonLabel = "\ud30c\uc77c \uc120\ud0dd", placeholder = "\ucf54\ub4dc\ubd81 \ud30c\uc77c (\uc5ec\ub7ec \uac1c \uac00\ub2a5)", width = "100%"),
              p(class = "hint", "Excel, CSV, \ud14d\uc2a4\ud2b8\ud615 PDF (\uc5ec\ub7ec \ud30c\uc77c \uc120\ud0dd \uac00\ub2a5)"),
              p(class = "hint", "\uc2a4\uce94 PDF\uc758 \ubb38\uc790\ub294 \uc77d\uc9c0 \ubabb\ud569\ub2c8\ub2e4. \ubcf5\uc7a1\ud55c \ubb38\uc11c\ub294 \uc77d\uae30 \uacb0\uacfc\ub97c \ud655\uc778\ud558\uc138\uc694."),
              div(class = "feedback", role = "status", textOutput("book_feedback"))))),
          div(class = "example-strip", span("\ucc98\uc74c \uc0ac\uc6a9\ud558\uc2dc\ub098\uc694?"),
            actionButton("load_example", "\uc608\uc81c \uc790\ub8cc\uc640 \ucf54\ub4dc\ubd81\uc73c\ub85c \uc0b4\ud3b4\ubcf4\uae30", class = "btn-link")),
          conditionalPanel("output.ui_ready !== 'yes'",
            div(class = "next-step pending-step", role = "status", textOutput("ui_connection_hint"))),
          conditionalPanel("output.ui_ready === 'yes'",
