              ui_table("book_records", "\uc77d\uc5b4 \uc628 \ucf54\ub4dc\ubd81 \uc815\uc758"),
              p(class = "hint", "\ucc98\uc74c 35\uac1c \uc815\uc758\uc785\ub2c8\ub2e4."), verbatimTextOutput("book_excerpts"))),
          conditionalPanel("output.ui_has_data === 'yes'",
            tags$details(tags$summary("\uc790\ub8cc\ud615\uacfc \uae30\uc874 \ub77c\ubca8"), ui_table("metadata_table", "\uc6d0\uc790\ub8cc\uc758 \uc790\ub8cc\ud615\uacfc \ub77c\ubca8"),
              p(class = "hint", "\ucd5c\ub300 120\uac1c \ubcc0\uc218\uc785\ub2c8\ub2e4. SPSS \uc9c0\uc815 \uacb0\uce21 \ucf54\ub4dc\ub294 \uc6d0\ub798 \ucf54\ub4dc\uc640 \uc18d\uc131\uc744 \uc720\uc9c0\ud558\uba70 \uacb0\uce21 \uc218\uc5d0 \ud3ec\ud568\ud569\ub2c8\ub2e4.")))
        ),
        tabPanel("2  \uac80\ud1a0\uc640 \uc801\uc6a9", value = "codebook",
