                      textInput("review_reason", "\ud655\uc778 \ub610\ub294 \ubcf4\ub958\ud55c \uc774\uc720", ""),
                      actionButton("save_decision", "\uac80\ud1a0 \uae30\ub85d \uc800\uc7a5")))),
                div(class = "preview-box", h3("\uc801\uc6a9 \uc804\ud6c4 \ubbf8\ub9ac\ubcf4\uae30"),
