                  div(class = "feedback", role = "status", textOutput("review_metadata_note")),
                  ui_table("review_metadata", "\ubcc0\uc218 \uc124\uba85\uacfc \uac12 \ub77c\ubca8\uc758 \uc801\uc6a9 \uc804\ud6c4 \ube44\uad50"),
                  h4("\uc790\ub8cc \uac12"),
                  ui_table("review_sample", "\uc120\ud0dd\ud55c \uc791\uc5c5\uc758 \uc801\uc6a9 \uc804\ud6c4 \ubbf8\ub9ac\ubcf4\uae30"),
                  p(class = "hint", "\ucc98\uc74c 12\ud589\uc785\ub2c8\ub2e4. \uc790\ub8cc \ud615\ud0dc\ub97c \ubc14\uafb8\uba74 \uacb0\uacfc\ub97c \ucd5c\ub300 10\uc5f4\uae4c\uc9c0 \ud45c\uc2dc\ud569\ub2c8\ub2e4.")))),
            tags$details(tags$summary("\uc804\uccb4 \ubcc0\uc218\uc758 \ud655\uc778\uc0ac\ud56d"), ui_table("review_overview", "\uc804\uccb4 \ubcc0\uc218 \ud655\uc778\uc0ac\ud56d")),
