            tags$details(tags$summary("\ucc98\ub9ac \ud6c4 \ucf54\ub4dc\ubd81\uacfc \ub2e4\uc2dc \ub300\uc870\ud55c \uacb0\uacfc"), ui_table("post_review", "\ucc98\ub9ac \ud6c4 \ucf54\ub4dc\ubd81 \ub300\uc870")),
